serde_json::json!({
    "api_base": { "description": "Base URL of the Compresr API. Falls back to the COMPRESR_API_BASE env var, then https://api.compresr.ai. Point at your internal service URL for on-prem deployments.", "required": false, "type": "string" },
    "api_key": { "description": "Compresr API key. Falls back to the COMPRESR_API_KEY env var.", "required": false, "type": "string" },
    "model": { "description": "Compresr compression model (not the LLM). Defaults to 'latte_v2', the query-aware compression model.", "required": false, "type": "string" },
    "optional_params": { "description": "Optional parameters for the guardrail", "fields": { "allow_bypass_header": { "description": "Honor the `x-compresr-bypass: true` request header to skip compression for a single call. Off by default because the header is caller-settable; enable only on trusted deployments.", "required": false, "type": "boolean" }, "coarse": { "description": "Paragraph-level compression (default, faster) instead of token-level (finer-grained).", "required": false, "type": "boolean" }, "compress_history": { "description": "Also compress prior (non-last) user messages. Defaults to False.", "required": false, "type": "boolean" }, "compress_last_user": { "description": "Also compress the last user message. The query sent to Compresr is always the original verbatim text. Defaults to False.", "required": false, "type": "boolean" }, "compress_system": { "description": "Also compress system messages. Defaults to False.", "required": false, "type": "boolean" }, "compress_tool_outputs": { "description": "Compress tool/function result messages (search hits, RAG chunks, API dumps). Defaults to True.", "required": false, "type": "boolean" }, "compression_params": { "description": "Passthrough of extra parameters forwarded verbatim in the Compresr compress payload (e.g. `heuristic_chunking`, or any newer knob), so a new Compresr feature works without a guardrail update. The named fields above take precedence on collision.", "dict_value_type": "string", "required": false, "type": "dict" }, "dynamic": { "description": "latte_v2 only. Let the server choose the compression amount per input (Kneedle elbow) instead of using target_compression_ratio. Defaults to True.", "required": false, "type": "boolean" }, "dynamic_max_ratio": { "description": "latte_v2 only. Ceiling on the adaptive ratio when `dynamic` is on. Unset lets the server default apply (~10.0).", "required": false, "type": "number" }, "dynamic_min_ratio": { "description": "latte_v2 only. Floor on the adaptive ratio when `dynamic` is on. Unset lets the server default apply (~1.5).", "required": false, "type": "number" }, "enable_retrieval": { "description": "Make compression recoverable: inject a `compresr_retrieve` tool so the model can fetch the original content behind a compression marker via the agentic loop. Defaults to True. Set to False (or run the proxy with --workers 1) for multi-worker deployments: the recovery store is per-process, so pre-call and retrieval hooks on different workers cannot see each other's originals.", "required": false, "type": "boolean" }, "max_bytes_per_call": { "description": "Cap on aggregate bytes of stored originals per litellm_call_id. When a call exceeds this, oldest entries are evicted so the in-process store cannot grow without bound. Defaults to 10 MiB.", "required": false, "type": "number" }, "min_chars_to_compress": { "description": "Skip messages whose text is shorter than this many characters. Defaults to 500.", "required": false, "type": "number" }, "target_compression_ratio": { "description": "Compression strength. 0-1 is the fraction of tokens to remove (0.5 = remove ~50%, the default); a value >1 is an Nx reduction factor (e.g. 4 = ~4x smaller).", "required": false, "type": "number" } }, "required": false, "type": "nested" },
    "ui_friendly_name": "Compresr (context compression)",
    "unreachable_fallback": { "default_value": "fail_closed", "description": "Behavior when the Compresr compression service is unreachable or errors. 'fail_closed' raises an error (default). 'fail_open' logs a critical error and forwards the request uncompressed instead of blocking it.", "options": ["fail_closed", "fail_open"], "required": false, "type": "select" },
})
